// Small built-in status font: no runtime font/ROMFS dependency in core runners.
inline void coreText(SDL_Renderer* r,const char* s,int x,int y,int scale){
 static const unsigned char glyphs[][5]={
 {0x7e,0x11,0x11,0x11,0x7e},{0x7f,0x49,0x49,0x49,0x36},{0x3e,0x41,0x41,0x41,0x22},{0x7f,0x41,0x41,0x22,0x1c},{0x7f,0x49,0x49,0x49,0x41},{0x7f,0x09,0x09,0x09,0x01},{0x3e,0x41,0x49,0x49,0x7a},{0x7f,0x08,0x08,0x08,0x7f},{0,0x41,0x7f,0x41,0},{0x20,0x40,0x41,0x3f,1},{0x7f,8,0x14,0x22,0x41},{0x7f,0x40,0x40,0x40,0x40},{0x7f,2,0x0c,2,0x7f},{0x7f,4,8,0x10,0x7f},{0x3e,0x41,0x41,0x41,0x3e},{0x7f,9,9,9,6},{0x3e,0x41,0x51,0x21,0x5e},{0x7f,9,0x19,0x29,0x46},{0x46,0x49,0x49,0x49,0x31},{1,1,0x7f,1,1},{0x3f,0x40,0x40,0x40,0x3f},{0x1f,0x20,0x40,0x20,0x1f},{0x7f,0x20,0x18,0x20,0x7f},{0x63,0x14,8,0x14,0x63},{7,8,0x70,8,7},{0x61,0x51,0x49,0x45,0x43},
 {0x3e,0x51,0x49,0x45,0x3e},{0,0x42,0x7f,0x40,0},{0x62,0x51,0x49,0x49,0x46},{0x22,0x41,0x49,0x49,0x36},{0x18,0x14,0x12,0x7f,0x10},{0x27,0x45,0x45,0x45,0x39},{0x3c,0x4a,0x49,0x49,0x30},{1,0x71,9,5,3},{0x36,0x49,0x49,0x49,0x36},{6,0x49,0x49,0x29,0x1e}};
 for(;*s;s++,x+=6*scale){int c=std::toupper(static_cast<unsigned char>(*s)),index=c>='A'&&c<='Z'?c-'A':c>='0'&&c<='9'?26+c-'0':-1;if(index<0)continue;for(int col=0;col<5;col++)for(int row=0;row<7;row++)if(glyphs[index][col]&(1<<row)){SDL_Rect p{x+col*scale,y+row*scale,scale,scale};SDL_RenderFillRect(r,&p);}}
}
inline void coreStatus(SDL_Renderer* r,const char* title){if(!r)return;SDL_SetRenderDrawColor(r,25,28,34,255);SDL_RenderClear(r);SDL_SetRenderDrawColor(r,230,36,53,255);SDL_Rect bar{70,230,1140,6};SDL_RenderFillRect(r,&bar);SDL_SetRenderDrawColor(r,243,244,247,255);coreText(r,"AI1 EMU",74,170,5);coreText(r,title,74,285,3);SDL_SetRenderDrawColor(r,177,182,192,255);coreText(r,"HOLD PLUS AND MINUS TO RETURN",74,390,2);SDL_RenderPresent(r);}
